/* V2.9 operational workflow completion. One source owner per record.
 * Browser persistence and actor selectors are interaction references, not access control. */
'use strict';
const WF29_EFFECTS=['Effective','Partially effective','Ineffective'];
const WF29_FREQUENCIES=['Per transaction','Daily','Weekly','Monthly','Quarterly','Annually','Event driven'];
const wf29Categories=()=>[...new Set([...CS_SEED.risks.map(r=>r.category),'Technology','Process','Fraud','Third-party','People','External'])];
const WF29_VENDOR_REQUESTS=['Periodic review','Activate service','Suspend service','Resume service','Exit service'];
function wf29Init(){S.workflowCompletion??={version:1,drafts:{},rcsaDrafts:{},controlTests:[],vendorReviews:[],history:[]};}
const wf29State=()=>S.workflowCompletion;
const wf29Person=name=>CS_SEED.people.includes(name);
const wf29Now=()=>new Date().toISOString();
function wf29Log(type,id,message,details={}){const entry={id:uid('WFH'),type,recordId:id,message,actor:recActor().name,at:wf29Now(),...clone(details)};wf29State().history.push(entry);audit(message,id,entry.actor);return entry;}
function wf29Emit(event){window.CS_V28_EVENTS?.emit(event);}
function wf29Replacement(workflow,record){const control=workflow==='control-test',collection=wf29State()[control?'controlTests':'vendorReviews'],ownerKey=control?'controlId':'engagementId';return collection.find(r=>r.corrects===record.id&&r[ownerKey]===record[ownerKey]);}
function wf29ReturnNotice(workflow,review,source,decision){if(review.status!=='Changes requested')return;const control=workflow==='control-test';wf29Emit({id:(control?'control-test-returned-':'vendor-review-returned-')+review.id,type:'program',title:(control?'Correct control test: ':'Revise service review: ')+(control?source.title:source.service),body:decision.note,sourceType:control?'control':'engagement',sourceId:source.id,sourceWorkflow:workflow,sourceReviewId:review.id,sourceState:'Changes requested',sourceRoute:workflow+'?id='+source.id+'&'+(control?'test':'review')+'='+review.id,orgScopeId:control?wf29ControlScopes(source)[0]||'':source.orgScopeId,recipient:control?review.tester:review.requestedBy,actor:decision.reviewer,severity:'Normal',actionable:true});}
function wf29CorrectionLink(workflow,review){const replacement=wf29Replacement(workflow,review),control=workflow==='control-test';return replacement?link('Open replacement review',workflow+'?id='+review[control?'controlId':'engagementId']+'&'+(control?'test':'review')+'='+replacement.id,'primary'):btn(control?'Prepare corrected test':'Prepare revised request',control?'wf29-test-correct':'wf29-vendor-correct',`data-id="${review.id}"`,'primary');}
function wf29History(type,id){const rows=wf29State().history.filter(x=>x.type===type&&x.recordId===id);return rows.length?`<ol class="timeline">${rows.slice().reverse().map(x=>`<li><strong>${e(x.message)}</strong><small>${e(x.actor)} · ${e(recTimestamp(x.at))}</small>${x.reason?`<p>${e(x.reason)}</p>`:''}</li>`).join('')}</ol>`:empty('No changes recorded','Saved changes and review decisions will appear here.');}
function wf29Record(type,id){const r=recRead(type,id);requireValue(r,'The requested record is unavailable.');requireValue(!S.scopeInvalid&&recInScope(type,r),'The record is outside the selected organizational scope.');return r;}
function wf29NotFound(type,back){return uxUnavailable('The requested '+type+' is unavailable in the selected scope.',back);}
const wf29Field=(name,label,value='',type='text',extra='')=>input(name,label,value,type,`data-wf29-field="${name}" ${extra}`);
const wf29Text=(name,label,value='',extra='')=>area(name,label,value,`data-wf29-field="${name}" ${extra}`);
const wf29Select=(name,label,list,value,extra='')=>select(name,label,list,value,`data-wf29-field="${name}" ${extra}`);
function wf29ScopeChoices(scope=selectedScope()){return [['','Choose accountable location'],...ORG.filter(n=>!scope||orgWithin(n.id,scope)).map(n=>[n.id,orgName(n.id)])];}
function wf29ControlScopes(c){return c.orgScopeId?[c.orgScopeId]:scopeIds(c,'controls');}
function wf29ControlMatches(c,scope){return wf29ControlScopes(c).some(id=>orgWithin(id,scope)||orgWithin(scope,id));}
function wf29CommonScope(ids){if(!ids.length)return '';let common=orgPath(ids[0]);for(const id of ids.slice(1))common=common.filter(n=>orgPath(id).some(x=>x.id===n.id));return common.at(-1)?.id||'';}
function wf29ControlDigest(c){return recHashText(recStable({id:c.id,title:c.title,scopeIds:wf29ControlScopes(c).slice().sort(),owner:c.owner,description:c.description||'',objective:c.objective||'',frequency:c.frequency||'',execution:c.execution||'',procedureRef:c.procedureRef||'',reqs:[...c.reqs].sort(),risks:[...c.risks].sort(),revision:c.definitionRevision||0}));}
function wf29Draft(kind,id='new'){return wf29State().drafts[kind+':'+id];}
function wf29StartControl(id='new'){
 wf29Init();const c=id==='new'?null:wf29Record('control',id),key='control:'+id;
 if(!wf29State().drafts[key])wf29State().drafts[key]={kind:'control',sourceId:id,scopeAtStart:c?wf29CommonScope(wf29ControlScopes(c)):selectedScope(),baseDigest:c?wf29ControlDigest(c):'',values:c?{title:c.title,owner:c.owner,orgScopeId:c.orgScopeId||wf29CommonScope(wf29ControlScopes(c)),description:c.description||'',objective:c.objective||'',frequency:c.frequency||'Monthly',execution:c.execution||'Manual',procedureRef:c.procedureRef||'',reqs:clone(c.reqs),risks:clone(c.risks),reason:''}:{title:'',owner:recActor().name,orgScopeId:selectedScope(),description:'',objective:'',frequency:'Monthly',execution:'Manual',procedureRef:'',reqs:[],risks:[],reason:''}};
 save();go('control-editor?id='+id);
}
function wf29ControlEditor(){wf29Init();const id=current.params.get('id')||'new',d=wf29Draft('control',id);if(!d)return header('Control draft unavailable','Start from the control library.',link('Controls','controls'));const c=id==='new'?null:recRead('control',id);if(c&&!recInScope('control',c))return wf29NotFound('control','controls');const v=d.values,risks=S.risks.filter(r=>(!d.scopeAtStart||orgWithin(r.orgScopeId,d.scopeAtStart))&&(!v.orgScopeId||orgWithin(r.orgScopeId,v.orgScopeId)||orgWithin(v.orgScopeId,r.orgScopeId)));
 return header(id==='new'?'Create a control implementation':'Edit '+e(c.title),'Describe the work performed, accountable location and assurance objective. Changes remain a draft until saved.',link('Back to controls','controls')+btn('Save control','wf29-control-save',`data-id="${id}"`,'primary'),'Control configuration')+`<div class="wf29-draft-state">${icon('clock')} Draft saved as you type · scope stays pinned to this record</div><div id="wf29-error" class="form-error" role="alert"></div><form data-wf29-draft="control:${id}"><section class="panel pad"><div class="field-grid">${wf29Field('title','Control name',v.title,'text','maxlength="160"')}${wf29Select('owner','Accountable owner',CS_SEED.people,v.owner)}${wf29Select('orgScopeId','Implementation location',wf29ScopeChoices(d.scopeAtStart),v.orgScopeId)}${wf29Select('frequency','Operating frequency',WF29_FREQUENCIES,v.frequency)}${wf29Select('execution','Execution',['Manual','Automated','Hybrid'],v.execution)}${wf29Field('procedureRef','Procedure / system reference',v.procedureRef)}<div class="full">${wf29Text('objective','What should this control prevent or detect?',v.objective)}</div><div class="full">${wf29Text('description','How the control operates',v.description)}</div></div></section><section class="panel pad mt16"><h2>Requirement mappings</h2><p>Select the obligations this implementation supports. Mapping does not establish satisfaction.</p><div class="wf29-choices">${R.map(r=>`<label class="checkbox-row"><input type="checkbox" data-wf29-array="reqs" value="${r.id}" ${v.reqs.includes(r.id)?'checked':''}><span><strong>${e(r.code)}</strong> ${e(r.title)}</span></label>`).join('')}</div></section><section class="panel pad mt16"><h2>Supported risks</h2><p>Primary control links remain accountable in the risk record. A primary link must be reassigned there before it can be removed here.</p><div class="wf29-choices">${risks.length?risks.map(r=>`<label class="checkbox-row"><input type="checkbox" data-wf29-array="risks" value="${r.id}" ${v.risks.includes(r.id)?'checked':''} ${r.control===id?'disabled':''}><span>${e(r.title)}<small>${e(orgName(r.orgScopeId))}${r.control===id?' · primary control':''}</small></span></label>`).join(''):notice('No risks in this implementation location. You can link a risk after registering it.','mini')}</div></section><section class="panel pad mt16">${wf29Text('reason','Reason for creating or changing this implementation',v.reason)}<div class="wf29-actions">${btn('Discard draft','wf29-discard',`data-key="control:${id}" data-route="controls"`,'quiet')}${btn('Save control','wf29-control-save',`data-id="${id}"`,'primary')}</div></section></form>`;
}
function wf29SaveControl(id){const d=wf29Draft('control',id);requireValue(d,'Control draft unavailable.');const v=d.values,c=id==='new'?null:wf29Record('control',id);if(c)requireValue(wf29ControlDigest(c)===d.baseDigest,'This control changed after the draft began. Discard the draft and reopen the current record.');requireValue(v.title.trim().length>=3&&v.objective.trim().length>=15&&v.description.trim().length>=20,'Enter a control name, specific objective and operating procedure.');requireValue(wf29Person(v.owner)&&orgNode(v.orgScopeId),'Choose a known owner and accountable location.');requireValue(!d.scopeAtStart||orgWithin(v.orgScopeId,d.scopeAtStart),'The location must remain within the scope where this draft was started.');requireValue(WF29_FREQUENCIES.includes(v.frequency)&&['Manual','Automated','Hybrid'].includes(v.execution),'Choose the operating frequency and execution method.');requireValue(v.procedureRef.trim().length>=3&&v.reason.trim().length>=12,'Record a procedure reference and a meaningful change reason.');requireValue(v.reqs.length&&v.reqs.every(r=>findR(r)),'Map at least one valid requirement.');requireValue(v.risks.every(rid=>{const r=recRead('risk',rid);return r&&(orgWithin(r.orgScopeId,v.orgScopeId)||orgWithin(v.orgScopeId,r.orgScopeId));}),'All linked risks must lie within the control implementation scope.');if(c){for(const r of S.risks.filter(r=>r.control===c.id))requireValue(v.risks.includes(r.id),'Reassign the primary control on '+r.id+' before removing this risk link.');}
 const next={...(c||{}),id:c?.id||uid('CTL'),title:v.title.trim(),owner:v.owner,orgScopeId:v.orgScopeId,unit:orgNode(v.orgScopeId).name,description:v.description.trim(),objective:v.objective.trim(),frequency:v.frequency,execution:v.execution,procedureRef:v.procedureRef.trim(),reqs:[...new Set(v.reqs)],risks:[...new Set(v.risks)],definitionRevision:(c?.definitionRevision||0)+1,effectiveness:c?.effectiveness||'Not assessed'};
 if(c){const operationalKeys=['orgScopeId','description','objective','frequency','execution','procedureRef','reqs'];const before=Object.fromEntries(operationalKeys.map(k=>[k,c[k]??''])),after=Object.fromEntries(operationalKeys.map(k=>[k,next[k]??'']));if(recStable(before)!==recStable(after)){next.previousEffectiveness={value:c.effectiveness,lastTestId:c.lastTestId||'',changedOn:S.asOf};next.effectiveness='Not assessed';}Object.assign(c,next);}else S.controls.unshift(next);delete wf29State().drafts['control:'+id];wf29Log('control',next.id,c?'Updated control implementation':'Created scoped control implementation',{reason:v.reason,before:c?d.baseDigest:'',after:wf29ControlDigest(next)});go('control?id='+next.id);toast('Control saved. Test it before changing its effectiveness conclusion.');
}
function wf29ControlView(){const c=recRead('control',current.params.get('id'));if(!c||!recInScope('control',c))return wf29NotFound('control','controls');const tests=wf29State().controlTests.filter(t=>t.controlId===c.id),latest=tests.filter(t=>t.status==='Approved').at(-1);return header(e(c.title),e(wf29ControlScopes(c).map(orgName).join(' · ')),btn('Edit implementation','wf29-control-edit',`data-id="${c.id}"`)+btn('Record a control test','wf29-control-test',`data-id="${c.id}"`,'primary'),'Control implementation')+metricRow([metric('Effectiveness',pill(c.effectiveness),latest?(c.effectiveness==='Not assessed'?'Implementation requires a new test; prior accepted test '+latest.id:'Accepted test '+latest.id):'Existing reported conclusion; test basis not captured'),metric('Accountable owner',e(c.owner),c.frequency||'Frequency not recorded','users'),metric('Mapped requirements',c.reqs.length,'Assessed independently in each program'),metric('Linked risks',c.risks.length,'Risk ratings remain governed through RCSA')])+`<div class="wf29-two"><section class="panel pad"><h2>How the control operates</h2><dl class="wf29-facts"><div><dt>Objective</dt><dd>${e(c.objective||'Not captured — complete the implementation details.')}</dd></div><div><dt>Procedure</dt><dd>${e(c.description||'Not captured')}</dd></div><div><dt>Execution / frequency</dt><dd>${e(c.execution||'Not captured')} · ${e(c.frequency||'Not captured')}</dd></div><div><dt>Procedure reference</dt><dd>${e(c.procedureRef||'Not captured')}</dd></div></dl></section>${panel('Requirement and risk context','Open the underlying source before drawing an assurance conclusion.',`<div class="pad">${c.reqs.map(rid=>{const r=findR(rid);return `<div class="wf29-source-row"><strong>${e(r?.code||rid)}</strong><span>${e(r?.title||'Requirement unavailable')}</span></div>`;}).join('')}<hr class="divider">${c.risks.map(rid=>{const r=recRead('risk',rid);return `<div class="wf29-source-row"><span class="grow">${e(r?.title||rid)}</span>${r?link('Open risk','risk?id='+rid,'small'):pill('Unavailable','amber')}</div>`;}).join('')}</div>`)}</div>`+panel('Control tests and independent conclusions','Submitted test observations do not change effectiveness until an independent reviewer accepts them.',tests.length?table(['Test / period','Testing result','Review state',''],tests.slice().reverse().map(t=>({cells:[`<strong>${e(t.id)}</strong><small>${date(t.periodFrom)}–${date(t.periodTo)}</small>`,`${t.exceptions} exceptions in ${t.sample} samples<small>${e(t.recommendation)}</small>`,pill(t.status),link(t.status==='Submitted'?'Review test':'Open test',`control-test?id=${c.id}&test=${t.id}`,'small')]}))):empty('No documented test runs','Record the period, method, population, sample and supporting evidence.'))+panel('Implementation history','Changes do not rewrite accepted test snapshots.',wf29History('control',c.id));}
function wf29StartTest(id){const c=wf29Record('control',id),key='control-test:'+id;wf29State().drafts[key]??={kind:'control-test',sourceId:id,baseDigest:wf29ControlDigest(c),values:{periodFrom:S.asOf.slice(0,7)+'-01',periodTo:S.asOf,testedOn:S.asOf,tester:recActor().name,reviewer:'Ifeoma Nwosu',population:'',sample:'',exceptions:'',method:'',results:'',exceptionHandling:'',evidenceRef:'',documentVersionId:'',recommendation:'Partially effective'}};save();go('control-test?id='+id);}
function wf29TestView(){const c=recRead('control',current.params.get('id'));if(!c||!recInScope('control',c))return wf29NotFound('control test','controls');const id=current.params.get('test'),t=id?wf29State().controlTests.find(t=>t.id===id&&t.controlId===c.id):null,d=wf29Draft('control-test',c.id);if(id&&!t)return wf29NotFound('test snapshot','control?id='+c.id);if(!id&&!d)return header('No control test in preparation','Start a test from this control.',btn('Start test','wf29-control-test',`data-id="${c.id}"`,'primary'));
 const v=t||d.values,readonly=!!t,docs=S.governance.documents.filter(doc=>docVisible(doc)&&docCanLink(doc,{type:'control',id:c.id}));const heading=header(t?'Control test '+e(t.id):'Record a control test',e(c.title)+' · '+e(wf29ControlScopes(c).map(orgName).join(' · ')),link('Back to control','control?id='+c.id),'Control assurance');
 if(readonly)return heading+metricRow([metric('State',pill(t.status),'Submitted observations are locked'),metric('Sample coverage',t.sample+' / '+t.population,'Explicit population and sampled items'),metric('Exceptions',t.exceptions,'Exceptions need a documented disposition'),metric('Tested by',e(t.tester),date(t.testedOn),'users')])+`<div class="wf29-two"><section class="panel pad"><h2>Submitted test record</h2><dl class="wf29-facts">${[['Period',date(t.periodFrom)+'–'+date(t.periodTo)],['Method',t.method],['Observed results',t.results],['Exception handling',t.exceptionHandling||'No exceptions reported'],['Evidence reference',t.evidenceRef],['Proposed effectiveness',t.recommendation]].map(([k,v])=>`<div><dt>${k}</dt><dd>${e(v)}</dd></div>`).join('')}</dl>${t.documentVersionId&&docVersion(t.documentVersionId)?link('Open pinned evidence',`document?id=${docVersion(t.documentVersionId).documentId}&version=${t.documentVersionId}`,'small'):''}</section>${t.status==='Submitted'?`<form data-wf29-submit="control-decision" data-id="${t.id}" class="panel pad"><h2>Independent review</h2><p>Accept the test conclusion or request a corrected run. The risk register and program conclusions are unaffected.</p>${select('reviewer','Reviewer',CS_SEED.people,t.reviewer||'Ifeoma Nwosu')}${select('decision','Decision',['Approve test','Request changes'],'Request changes')}${area('note','Decision rationale','','required minlength="15"')}<div class="form-error" role="alert"></div><button type="submit" class="btn primary mt16">Record decision</button></form>`:`<section class="panel pad"><h2>Recorded decision</h2><p>${e(t.decision?.note||'No decision recorded')}</p><p>${e(t.decision?.reviewer||'')} · ${t.decision?date(t.decision.date):''}</p>${t.status==='Changes requested'?wf29CorrectionLink('control-test',t):''}</section>`}</div>`;
 return heading+`<div id="wf29-error" class="form-error" role="alert"></div><form data-wf29-draft="control-test:${c.id}"><section class="panel pad"><div class="field-grid">${wf29Field('periodFrom','Period from',v.periodFrom,'date')}${wf29Field('periodTo','Period to',v.periodTo,'date')}${wf29Field('testedOn','Test performed on',v.testedOn,'date')}${wf29Select('tester','Test performed by',CS_SEED.people,v.tester)}${wf29Select('reviewer','Independent reviewer',CS_SEED.people,v.reviewer)}${wf29Field('population','Population size',v.population,'number','min="1" step="1"')}${wf29Field('sample','Sample size',v.sample,'number','min="1" step="1"')}${wf29Field('exceptions','Exceptions found',v.exceptions,'number','min="0" step="1"')}${wf29Select('recommendation','Proposed effectiveness',WF29_EFFECTS,v.recommendation)}<div class="full">${wf29Text('method','Test method and sample selection',v.method)}</div><div class="full">${wf29Text('results','Results and basis for the proposed conclusion',v.results)}</div><div class="full">${wf29Text('exceptionHandling','Exception disposition / corrective action',v.exceptionHandling)}</div>${wf29Field('evidenceRef','Evidence or working-paper reference',v.evidenceRef)}${wf29Select('documentVersionId','Pin a supporting document (optional)',[['','Reference only'],...docs.map(doc=>[doc.currentVersionId,doc.title+' · '+docVersionLabel(docHead(doc))])],v.documentVersionId)}</div><div class="wf29-actions">${btn('Discard draft','wf29-discard',`data-key="control-test:${c.id}" data-route="control?id=${c.id}"`,'quiet')}${btn('Save & return','wf29-save-exit',`data-route="control?id=${c.id}"`)}${btn('Submit for review','wf29-test-submit',`data-id="${c.id}"`,'primary')}</div></section></form>`;
}
function wf29SubmitTest(id){const c=wf29Record('control',id),d=wf29Draft('control-test',id);requireValue(d,'Test draft unavailable.');requireValue(wf29ControlDigest(c)===d.baseDigest,'The control implementation changed. Start a new test against the current definition.');const v=clone(d.values);for(const k of ['periodFrom','periodTo','testedOn'])validDate(v[k],k);requireValue(v.periodFrom<=v.periodTo&&v.periodTo<=v.testedOn,'The period must end before or on the test date.');requireValue(wf29Person(v.tester)&&wf29Person(v.reviewer)&&v.tester!==v.reviewer,'Choose a known tester and a different independent reviewer.');v.population=bounded(v.population,1,100000000,'Population');v.sample=bounded(v.sample,1,v.population,'Sample size');v.exceptions=bounded(v.exceptions,0,v.sample,'Exception count');requireValue(v.method.trim().length>=15&&v.results.trim().length>=20,'Record the sampling method and substantive results.');requireValue(WF29_EFFECTS.includes(v.recommendation),'Select a valid proposed effectiveness.');requireValue(!v.exceptions||v.exceptionHandling.trim().length>=15,'Explain the disposition of the exceptions found.');requireValue(v.evidenceRef.trim().length>=3,'Provide the evidence or working-paper reference.');if(v.documentVersionId){const ver=docVersion(v.documentVersionId),doc=ver&&recRead('document',ver.documentId);requireValue(doc&&docVisible(doc)&&docCanLink(doc,{type:'control',id}),'The selected evidence is unavailable or outside this control scope.');}
 const t={...v,id:uid('CTEST'),controlId:id,controlSnapshot:clone(c),definitionDigest:d.baseDigest,status:'Submitted',submittedAt:S.asOf,revision:wf29State().controlTests.filter(t=>t.controlId===id).length+1,corrects:d.corrects||''};wf29State().controlTests.push(t);delete wf29State().drafts['control-test:'+id];wf29Log('control',id,'Submitted control test '+t.id,{testId:t.id});wf29Emit({id:'control-test-'+t.id,type:'approval',title:'Review control test: '+c.title,body:t.results,sourceType:'control',sourceId:id,sourceWorkflow:'control-test',sourceReviewId:t.id,sourceRoute:`control-test?id=${id}&test=${t.id}`,orgScopeId:wf29ControlScopes(c)[0]||'',recipient:t.reviewer,actor:t.tester,severity:'medium',actionable:true});go(`control-test?id=${id}&test=${t.id}`);}
function wf29TestDecision(form){const t=wf29State().controlTests.find(t=>t.id===form.dataset.id);requireValue(t,'Test not found.');const c=wf29Record('control',t.controlId),v=values(form);requireValue(t.status==='Submitted','Only a submitted test can be reviewed.');requireValue(wf29Person(v.reviewer)&&v.reviewer!==t.tester,'The reviewer must be known and independent of the tester.');requireValue(['Approve test','Request changes'].includes(v.decision)&&v.note.trim().length>=15,'Choose a decision and give a substantive rationale.');if(v.decision==='Approve test'){requireValue(t.definitionDigest===wf29ControlDigest(c),'The control changed after the test. Request a corrected test.');if(t.documentVersionId)requireValue(docVersion(t.documentVersionId),'The pinned evidence version is unavailable.');}const before=clone(t);t.status=v.decision==='Approve test'?'Approved':'Changes requested';t.decision={...v,date:S.asOf};if(t.status==='Approved'){c.effectiveness=t.recommendation;c.lastTestId=t.id;c.effectivenessReviewedOn=S.asOf;}recDecision('control',c.id,v.reviewer,v.decision,v.note,{test:before,control:clone(t.controlSnapshot)},String(t.revision));wf29Log('control',c.id,'Control test '+t.status.toLowerCase(),{testId:t.id,reason:v.note,actor:v.reviewer});wf29ReturnNotice('control-test',t,c,v);render();toast('Test decision recorded. Risk and compliance conclusions remain separate.');}
function wf29RiskBasis(r,c){return {risk:{id:r.id,orgScopeId:r.orgScopeId,cause:r.cause,event:r.event,impact:r.impact,control:r.control,inherent:clone(r.inherent),appetite:r.appetite},control:{id:c?.id,reqs:clone(c?.reqs||[]),definitionDigest:c?wf29ControlDigest(c):''}};}
function wf29RcsaKey(c,r){return c.id+'::'+r.id;}
function wf29RcsaEvidence(c,r){const control=S.controls.find(x=>x.id===r.control);if(!control)return [];const qids=new Set(uniqueQ(control?.reqs||[]).map(q=>q.id));return S.evidence.filter(ev=>ev.target==='Meridian Bank'&&qids.has(ev.question)&&evQuality(ev)==='Current'&&scopeIds(ev,'evidence').some(s=>wf29ControlScopes(control).some(cs=>orgWithin(s,cs)||orgWithin(cs,s))));}
function wf29RcsaContext(cycleId,riskId){const c=wf29Record('rcsa',cycleId),r=wf29Record('risk',riskId);requireValue(c.risks.includes(r.id),'This risk is outside the frozen assessment population.');requireValue(wf29Person(c.owner)&&wf29Person(c.reviewer)&&c.owner!==c.reviewer,'Assign separate known first-line and review owners.');return {c,r};}
function wf29SaveRcsaDraft(cycleId,riskId,v){const {c,r}=wf29RcsaContext(cycleId,riskId);requireValue(!['Submitted','Approved'].includes(c.reviews[r.id]?.status),'This proposal is locked.');const allowed=['effectiveness','evidence','likelihood','impact','rationale'];const existing=wf29State().rcsaDrafts[wf29RcsaKey(c,r)]||{};wf29State().rcsaDrafts[wf29RcsaKey(c,r)]={...existing,...Object.fromEntries(allowed.filter(k=>v[k]!==undefined).map(k=>[k,v[k]])),savedAt:wf29Now()};save();}
const wf29OldRespondent=rcsaRespondent;
