jOperationStep=function(d,step){const html=wf29OriginalOperationStep(d,step);return d.kind==='risk'&&step===2?html+notice('Need a control for this location? Your risk draft will remain saved while you create the implementation. '+btn('Create scoped control','new-control','','small'),'mini'):html;};
const wf29OriginalWorkItems=workItems;
workItems=function(){
 const rows=wf29OriginalWorkItems();if(!S.workflowCompletion)return rows;
 for(const t of wf29State().controlTests){const pending=t.status==='Submitted',returned=t.status==='Changes requested'&&!wf29Replacement('control-test',t);if(!pending&&!returned)continue;const c=recRead('control',t.controlId);if(c&&recInScope('control',c))rows.push({id:(pending?'REVIEW-':'CORRECT-')+t.id,title:(pending?'Review control test · ':'Correct control test · ')+c.title,kind:pending?'Control test review':'Control test correction',owner:pending?t.reviewer:t.tester,due:addDays(pending?t.submittedAt:t.decision?.date||t.submittedAt,7),status:'Open',ref:c.id,orgScopeId:wf29ControlScopes(c)[0],source:pending?'control-review':'control-correction',route:`control-test?id=${c.id}&test=${t.id}`});}
 for(const r of wf29State().vendorReviews){const pending=r.status==='Submitted',returned=r.status==='Changes requested'&&!wf29Replacement('vendor-review',r);if(!pending&&!returned)continue;const t=recRead('engagement',r.engagementId);if(t&&recInScope('engagement',t))rows.push({id:(pending?'REVIEW-':'CORRECT-')+r.id,title:(pending?r.requestType:'Revise '+r.requestType.toLowerCase())+' · '+t.service,kind:pending?'Vendor lifecycle review':'Vendor review correction',owner:pending?r.reviewer:r.requestedBy,due:addDays(pending?r.submittedAt:r.decision?.date||r.submittedAt,7),status:'Open',ref:t.id,orgScopeId:t.orgScopeId,source:pending?'vendor-review':'vendor-correction',route:`vendor-review?id=${t.id}&review=${r.id}`});}
 return rows;
};
function wf29Safe(fn){return el=>{try{fn(el);}catch(err){const box=$('#wf29-error');if(box){box.textContent=err.message;box.scrollIntoView({block:'center'});}else toast(err.message);}};}
Object.assign(actions,{
 'new-control':()=>wf29StartControl(),'wf29-control-edit':el=>wf29StartControl(el.dataset.id),'wf29-control-save':wf29Safe(el=>wf29SaveControl(el.dataset.id)),
 'wf29-control-test':el=>wf29StartTest(el.dataset.id),'wf29-test-submit':wf29Safe(el=>wf29SubmitTest(el.dataset.id)),
 'wf29-test-correct':el=>{const t=wf29State().controlTests.find(t=>t.id===el.dataset.id);requireValue(t?.status==='Changes requested','This test is not awaiting a correction.');const c=wf29Record('control',t.controlId),replacement=wf29Replacement('control-test',t);if(replacement){go('control-test?id='+c.id+'&test='+replacement.id);return;}const existing=wf29Draft('control-test',t.controlId);if(existing){requireValue(existing.corrects===t.id,'A different control-test draft is already in progress. Resume or discard it before starting this correction.');go('control-test?id='+c.id);return;}const fields=['periodFrom','periodTo','testedOn','tester','reviewer','population','sample','exceptions','method','results','exceptionHandling','evidenceRef','documentVersionId','recommendation'];wf29State().drafts['control-test:'+c.id]={kind:'control-test',sourceId:c.id,baseDigest:wf29ControlDigest(c),corrects:t.id,values:Object.fromEntries(fields.map(k=>[k,t[k]??'']))};save();go('control-test?id='+c.id);},
 'wf29-save-exit':el=>{save();go(el.dataset.route);toast('Draft saved. Resume from the source workspace.');},
 'wf29-discard':el=>{delete wf29State().drafts[el.dataset.key];save();go(el.dataset.route);},
 'wf29-rcsa-exit':el=>{const form=el.closest('form');wf29SaveRcsaDraft(el.dataset.cycle,el.dataset.risk,values(form));go('rcsa');toast('Assessment draft saved. Open the same cycle and risk to resume.');},
 'activate-engagement':el=>wf29StartVendor(el.dataset.id,'Activate service'),'wf29-vendor-start':el=>wf29StartVendor(el.dataset.id),
 'wf29-vendor-submit':wf29Safe(el=>wf29SubmitVendor(el.dataset.id)),
 'wf29-vendor-correct':el=>{const r=wf29State().vendorReviews.find(r=>r.id===el.dataset.id);requireValue(r?.status==='Changes requested','This review is not awaiting a revision.');const t=wf29Record('engagement',r.engagementId),replacement=wf29Replacement('vendor-review',r);if(replacement){go('vendor-review?id='+t.id+'&review='+replacement.id);return;}const existing=wf29Draft('vendor-review',r.engagementId);if(existing){requireValue(existing.corrects===r.id,'A different service-review draft is already in progress. Resume or discard it before starting this correction.');go('vendor-review?id='+t.id);return;}const fields=['requestType','requestedBy','reviewer','performance','issues','reason','contractRef','nextReview','exitRef','disposition','exitPlan','sourceRef'];wf29State().drafts['vendor-review:'+t.id]={kind:'vendor-review',sourceId:t.id,baseDigest:wf29VendorDigest(t),corrects:r.id,values:Object.fromEntries(fields.map(k=>[k,r[k]??'']))};save();go('vendor-review?id='+t.id);},
 'wf29-risk-edit':el=>wf29StartRiskEdit(el.dataset.id),'wf29-risk-save':wf29Safe(el=>wf29SaveRisk(el.dataset.id))
});
document.addEventListener('input',ev=>{const el=ev.target,form=el.closest?.('[data-wf29-draft]');if(form&&el.matches('[data-wf29-field]')){const d=wf29State().drafts[form.dataset.wf29Draft];if(d){d.values[el.dataset.wf29Field]=el.value;save();}}const rcsa=el.closest?.('[data-wf29-rcsa]');if(rcsa&&el.matches('[data-wf29-rcsa-field]')){try{wf29SaveRcsaDraft(rcsa.dataset.cycle,rcsa.dataset.risk,{[el.name]:el.value});const state=$('#wf29-rcsa-saved');if(state)state.textContent='Draft saved in this browser';}catch(err){toast(err.message);}}});
document.addEventListener('change',ev=>{const el=ev.target,form=el.closest?.('[data-wf29-draft]');if(form){const d=wf29State().drafts[form.dataset.wf29Draft];if(!d)return;if(el.matches('[data-wf29-array]')){const key=el.dataset.wf29Array;d.values[key]=el.checked?[...new Set([...d.values[key],el.value])]:d.values[key].filter(x=>x!==el.value);save();}if(el.matches('[data-wf29-field]')){d.values[el.dataset.wf29Field]=el.value;save();if(['orgScopeId','requestType'].includes(el.dataset.wf29Field)){const y=scrollY;render();scrollTo(0,y);}}}const rcsa=el.closest?.('[data-wf29-rcsa]');if(rcsa&&el.matches('[data-wf29-rcsa-field]'))wf29SaveRcsaDraft(rcsa.dataset.cycle,rcsa.dataset.risk,{[el.name]:el.value});});
document.addEventListener('submit',ev=>{const form=ev.target;if(!form.dataset.wf29Submit)return;ev.preventDefault();try{if(form.dataset.wf29Submit==='control-decision')wf29TestDecision(form);if(form.dataset.wf29Submit==='vendor-decision')wf29VendorDecision(form);}catch(err){$('.form-error',form).textContent=err.message;}});
Object.assign(window.CS_JOURNEYS,{'control':wf29ControlView,'control-editor':wf29ControlEditor,'control-test':wf29TestView,'vendor-review':wf29VendorView,'risk-edit':wf29RiskEditor});
Object.assign(window.CS_JOURNEY_GROUPS,{'control-editor':'risks','control-test':'risks','vendor-review':'vendors','risk-edit':'risks'});
Object.assign(titles,{'control-editor':'Control implementation editor','control-test':'Control test and review','vendor-review':'Service review and lifecycle','risk-edit':'Risk context editor'});
const wf29PreviousRender=render;
render=function(){wf29Init();wf29PreviousRender();};
window.CLEAR_SIGHT_WORKFLOWS=Object.freeze({version:'2.9-design-reference',state:()=>clone(wf29State()),vendorGate:id=>clone(wf29VendorGate(recRead('engagement',id))),controlDigest:id=>wf29ControlDigest(recRead('control',id))});
